def f(I):
    H,W=len(I),len(I[0])
    bg=I[0][0]
    seen=[[False]*W for _ in range(H)]
    stack=[]
    for r in range(H):
        for c in range(W):
            if I[r][c]==bg and (r in(0,H-1) or c in(0,W-1)):
                seen[r][c]=True; stack.append((r,c))
    while stack:
        r,c=stack.pop()
        for dr,dc in [(1,0),(-1,0),(0,1),(0,-1)]:
            nr,nc=r+dr,c+dc
            if 0<=nr<H and 0<=nc<W and not seen[nr][nc] and I[nr][nc]==bg:
                seen[nr][nc]=True; stack.append((nr,nc))
    O=[row[:] for row in I]
    for r in range(H):
        for c in range(W):
            if I[r][c]==bg and not seen[r][c]:
                O[r][c]=1
    return O

