    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))
# hypothesis: fill bg cell if it is NOT reachable from grid border through bg cells (4-connectivity flood on non-bg only... wait earlier encls failed)
# try the reverse: flood from border through NON-bg cells; enclosed = bg cells unreachable.
def f(I):
    I=[row[:] for row in I]; H,W=len(I),len(I[0])
    bg=Counter(x for row in I for x in row).most_common(1)[0][0]
    vis=[[False]*W for _ in range(H)]; dq=deque()
    for r in range(H):
        for c in (0,W-1):
            if I[r][c]!=bg and not vis[r][c]: vis[r][c]=True; dq.append((r,c))
    for c in range(W):
        for r in (0,H-1):
            if I[r][c]!=bg and not vis[r][c]: vis[r][c]=True; dq.append((r,c))
    while dq:
        r,c=dq.popleft()
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            rr,cc=r+dr,c+dc
            if 0<=rr<H and 0<=cc<W and I[rr][cc]!=bg and not vis[rr][cc]:
                vis[rr][cc]=True; dq.append((rr,cc))
    out=[]
    for r in range(H):
        row=[]
        for c in range(W):
            if I[r][c]==bg and not vis[r][c]: row.append(1)
            else: row.append(I[r][c])
        out.append(row)
    return out
ok=True
for p in range(1,7):
    ii=G['Demo pair %s input'%p]; oo=G['Demo pair %s output'%p]
    s=f(ii)==oo
    ok=s and ok; print(p,'match:',s)
print('all:',ok)
res=f(G['Test input']); print(json.dumps(res))

